-- Pakistan EV catalog (brand then model). Public read; writes via service_role only.

CREATE TABLE IF NOT EXISTS public.ev_vehicles (
  id TEXT PRIMARY KEY,
  brand TEXT NOT NULL,
  model TEXT NOT NULL,
  vehicle_type TEXT,
  battery_capacity_kwh NUMERIC,
  range_km INTEGER,
  ac_charging_kw NUMERIC,
  dc_charging_kw NUMERIC,
  connector TEXT NOT NULL DEFAULT 'CCS2',
  price_pkr NUMERIC,
  source_url TEXT,
  source TEXT,
  scraped_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (brand, model)
);

CREATE INDEX IF NOT EXISTS ev_vehicles_brand_idx ON public.ev_vehicles (brand);

ALTER TABLE public.ev_vehicles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ev_vehicles_public_read ON public.ev_vehicles;
CREATE POLICY ev_vehicles_public_read ON public.ev_vehicles
  FOR SELECT USING (true);

ON CONFLICT (id) DO UPDATE SET
  brand = EXCLUDED.brand,
  model = EXCLUDED.model,
  vehicle_type = EXCLUDED.vehicle_type,
  battery_capacity_kwh = EXCLUDED.battery_capacity_kwh,
  range_km = EXCLUDED.range_km,
  ac_charging_kw = EXCLUDED.ac_charging_kw,
  dc_charging_kw = EXCLUDED.dc_charging_kw,
  connector = EXCLUDED.connector,
  price_pkr = EXCLUDED.price_pkr,
  source_url = EXCLUDED.source_url,
  source = EXCLUDED.source,
  scraped_at = EXCLUDED.scraped_at;
